	print("saved err:", err)
	# Verify count
	var instance = scene.instantiate()
	print("instance count:", _count_node2d(instance))
	instance.free()
	root.free()
	quit()

func _count_node2d(node: Node) -> int:
	var c = 1 if node is Node2D else 0
	for child in node.get_children():
		c += _count_node2d(child)
	return c
